// Fibra óptica · levantamiento de ruta y apoyos («Fibra · <comuna>»). The planilla «Tendido FO» of each comuna is the
// data contract (fibra_<Comuna>.json, generated by contrato_fibra.py): this screen walks a tramo from one end to the
// other, identifies each pole against the SEC catastro (or gives it the next free NC code), fills the yellow columns
// of «Apoyos» and, at the end, of «Ruta», and computes «Control», «Veredicto» and «Permisos del tramo» with the
// planilla's own rules (fibra-reglas.mjs). Everything is saved on the phone first; one JSON per record goes to the
// queue the office service reads. The survey is done from the ground: nobody climbs a pole.
import {chileDate,randomId} from './core.mjs';
import * as dropbox from './dropbox-client.mjs';
import {gpsLabel,processImage,withExif,requestFix} from './media.mjs';
import * as R from './fibra-reglas.mjs';

const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const COMUNAS=['Antofagasta','Calama','Tocopilla'];
const DB='visionaria-fibra-v1';
const BUSQUEDA={radio:15,precision:10};   // §8.3: candidates within 15 m; a fix worse than 10 m asks to confirm by the plate
const SEGURIDAD='El levantamiento se hace desde el suelo. No se sube a los postes.';
// The first screen of the pole card (§5.1); the rest of the yellow columns go on the second.
const PASO1=['¿Se encontró el poste?','Placa en terreno','Propietario u operador','Redes eléctricas en el poste','Espacio para la fibra','Estado físico',
  'Función para la fibra','Cruce en el vano siguiente','Altura libre prevista en el cruce (m)','Usar como apoyo','Motivo si no se usa'];
// Filled by the app: never typed (the GPS pair and the photo count) or set by the walk (tramo, date, who).
const AUTO=['Fecha','Levantó','Tramo levantado','Latitud medida','Longitud medida','Fotos tomadas (N°)'];
const COLOR={Apto:'var(--fo-apto)','No apto':'var(--fo-no)','A revisar':'var(--fo-revisar)','No encontrado':'var(--fo-nada)',Incompleto:'var(--fo-incompleto)'};

let ctx=null,K=null,comuna=null,vista={pantalla:'tramos'},registros=new Map(),fotos=[],busy=false,urls=[],timer=null,aqui=null,filtro={texto:'',nodo:''};
const contratos={};let idx=null;

// --- Storage ---------------------------------------------------------------------------------------------------------
let dbp;
const database=()=>dbp??=new Promise((ok,ko)=>{const r=indexedDB.open(DB,1);r.onupgradeneeded=()=>{r.result.createObjectStore('registros',{keyPath:'clave'});r.result.createObjectStore('fotos',{keyPath:'id'});};r.onsuccess=()=>ok(r.result);r.onerror=()=>ko(r.error);});
const all=async s=>{const d=await database();return new Promise((ok,ko)=>{const q=d.transaction(s).objectStore(s).getAll();q.onsuccess=()=>ok(q.result);q.onerror=()=>ko(q.error);});};
const put=async(s,rows)=>{const d=await database();return new Promise((ok,ko)=>{const tx=d.transaction(s,'readwrite');rows.forEach(r=>tx.objectStore(s).put(r));tx.oncomplete=()=>ok();tx.onerror=()=>ko(tx.error);});};
const del=async(s,ids)=>{const d=await database();return new Promise((ok,ko)=>{const tx=d.transaction(s,'readwrite');ids.forEach(i=>tx.objectStore(s).delete(i));tx.oncomplete=()=>ok();tx.onerror=()=>ko(tx.error);});};

// --- Contract ------------------------------------------------------------------------------------------------------
async function cargar(c){
  if(!contratos[c]){const r=await fetch(`/api/evidencias/assets/fibra_${c}.json`);if(!r.ok)throw new Error('No se pudo cargar la planilla de fibra de '+c+'.');contratos[c]=await r.json();}
  K=contratos[c];comuna=c;
  // Rows of each sheet as objects keyed by header (the grey, assignment and engineering columns).
  idx={};for(const [h,H] of Object.entries(K.hojas)){const m=new Map();for(const f of H.filas){const o={_fila:f[0]};H.fijas.forEach((k,i)=>o[k]=f[i+1]);m.set(String(o[H.codigo]),o);}idx[h]=m;}
}
const campo=(h,k)=>K.hojas[h].campos.find(c=>c.key===k);
const amarillas=h=>K.hojas[h].campos.filter(c=>c.rol==='amarillo');
const num=v=>{const n=parseFloat(String(v??'').replace(',','.'));return Number.isFinite(n)?n:null;};
const clave=(h,c)=>`${comuna}|${h}|${c}`;
const reg=(h,c)=>registros.get(clave(h,c));
const fotosDe=(h,c)=>fotos.filter(f=>f.clave===clave(h,c));
const distancia=(a,b)=>{const R0=6371000,r=x=>x*Math.PI/180,dLat=r(b.lat-a.lat),dLon=r(b.lon-a.lon),s=Math.sin(dLat/2)**2+Math.cos(r(a.lat))*Math.cos(r(b.lat))*Math.sin(dLon/2)**2;return 2*R0*Math.asin(Math.sqrt(s));};
const posicion=o=>{const lat=num(o.Latitud),lon=num(o.Longitud);return lat!==null&&lon!==null?{lat,lon}:null;};
const minFotos=(clave)=>R.parametro(K,clave);
const tomas=sufijo=>K.fotos.find(f=>f.sufijo===sufijo)?.tomas??[];

// Values as the rules and the planilla see them: fixed columns + what was typed (numbers as numbers) + the photo count.
function valores(h,codigo){
  const fijo=idx[h].get(codigo)??{},r=reg(h,codigo),v={...fijo};
  for(const [k,x] of Object.entries(r?.valores??{})){const c=campo(h,k);v[k]=c&&(c.type==='decimal'||c.type==='whole')?(num(x)??x):x;}
  const n=fotosDe(h,codigo).length;if(r||n)v['Fotos tomadas (N°)']=n;
  return v;
}
const apoyosDelTramo=t=>[...idx.Apoyos.values()].filter(a=>a['Tramo más próximo']===t||String(a['Todos los tramos próximos']??'').split(/[,;\s]+/).includes(t));
const levantadosEn=t=>[...registros.values()].filter(r=>r.comuna===comuna&&r.hoja==='Apoyos'&&r.valores['Tramo levantado']===t).map(r=>r.codigo);
function estadoApoyo(codigo){const v=valores('Apoyos',codigo),c=R.apoyoControl(K,v);return {control:c,veredicto:R.apoyoVeredicto(K,v,c)};}
function estadoRuta(t){
  const aptos=levantadosEn(t).filter(c=>estadoApoyo(c).veredicto==='Apto').length,v=valores('Ruta',t),c=R.rutaControl(K,v,aptos);
  return {control:c,permisos:R.rutaPermisos(K,v,c),aptos,levantados:levantadosEn(t).filter(c=>estadoApoyo(c).control!=='Sin levantar').length};
}
function estadoEnvio(h,codigo){
  const r=reg(h,codigo),fs=fotosDe(h,codigo);
  if(!r&&!fs.length)return {texto:'Sin datos',clase:''};
  if(r?.error)return {texto:'Error al enviar',clase:'error'};
  if(r?.sent&&r.sent.huella===huella(r)&&fs.every(f=>f.status==='sent'))return {texto:'Enviado',clase:'sent'};
  return {texto:r?.sent?'Cambios sin enviar':'Guardado en el teléfono',clase:'pending'};
}
const huella=r=>JSON.stringify([r.valores,fotosDe(r.hoja,r.codigo).map(f=>f.id).sort()]);

// --- Map: the tramo line and its candidate poles, drawn on the phone (works without signal) -------------------------
function mapa(lineas,puntos,yo){
  const todos=[...lineas.flat(),...puntos.map(p=>[p.lat,p.lon]),...(yo?[[yo.lat,yo.lon]]:[])];if(!todos.length)return '';
  const lats=todos.map(p=>p[0]),lons=todos.map(p=>p[1]),la0=Math.min(...lats),la1=Math.max(...lats),lo0=Math.min(...lons),lo1=Math.max(...lons);
  const k=Math.cos((la0+la1)/2*Math.PI/180),W=600,H=260,pad=16,ancho=Math.max((lo1-lo0)*k,1e-6),alto=Math.max(la1-la0,1e-6),e=Math.min((W-2*pad)/ancho,(H-2*pad)/alto);
  const X=lon=>pad+((lon-lo0)*k)*e+((W-2*pad)-ancho*e)/2,Y=lat=>H-pad-(lat-la0)*e-((H-2*pad)-alto*e)/2;
  return `<svg class="fo-mapa" viewBox="0 0 ${W} ${H}" role="img" aria-label="Trazado y postes candidatos">
    ${lineas.map(l=>`<polyline points="${l.map(p=>`${X(p[1]).toFixed(1)},${Y(p[0]).toFixed(1)}`).join(' ')}" fill="none" stroke="var(--green)" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>`).join('')}
    ${puntos.map(p=>`<circle cx="${X(p.lon).toFixed(1)}" cy="${Y(p.lat).toFixed(1)}" r="5" fill="${p.color}" stroke="#fff" stroke-width="1.5" data-fo-apoyo="${esc(p.codigo)}"><title>${esc(p.codigo)}</title></circle>`).join('')}
    ${yo?`<circle cx="${X(yo.lon).toFixed(1)}" cy="${Y(yo.lat).toFixed(1)}" r="7" fill="var(--fo-yo)" stroke="#fff" stroke-width="2"/>`:''}</svg>`;
}

// --- Screens -----------------------------------------------------------------------------------------------------------
function render(){
  const el=$('fibra-view');if(!el||!K)return;urls.forEach(URL.revokeObjectURL);urls=[];
  el.innerHTML=vista.pantalla==='tramo'?pantallaTramo():vista.pantalla==='apoyo'?pantallaApoyo():vista.pantalla==='ruta'?pantallaRuta():pantallaTramos();
}
function pantallaTramos(){
  const filas=[...idx.Ruta.values()].filter(t=>(!filtro.nodo||t['Nodo o central']===filtro.nodo)&&(!filtro.texto||String(t['ID tramo']).toLowerCase().includes(filtro.texto.toLowerCase())));
  const nodos=[...new Set([...idx.Ruta.values()].map(t=>t['Nodo o central']))];
  const estados=[...idx.Ruta.keys()].map(estadoRuta),ok=estados.filter(e=>e.control==='OK').length,lev=estados.filter(e=>e.control!=='Sin levantar').length;
  const km=([...idx.Ruta.values()].reduce((s,t)=>s+(num(t['Longitud de diseño (m)'])??0),0)/1000).toFixed(1).replace('.',',');
  let grupo='';
  return `<p class="lev-aviso">${esc(SEGURIDAD)} Levantamiento de observación: no se contacta ni se ingresa nada en CGE, el municipio ni Vialidad.</p>
    <p class="lev-conteo"><strong>${idx.Ruta.size} tramos · ${km} km de diseño</strong> · ${lev} con ruta levantada · ${ok} con ruta OK · ${idx.Apoyos.size} postes candidatos</p>
    <div class="records-toolbar"><label class="lev-filtro">Nodo<select id="fo-nodo"><option value="">Todos</option>${nodos.map(n=>`<option${n===filtro.nodo?' selected':''}>${esc(n)}</option>`).join('')}</select></label>
    <label class="lev-filtro">Buscar<input id="fo-buscar" value="${esc(filtro.texto)}" placeholder="Código del tramo" autocomplete="off"></label></div>
    <div class="lev-lista">${filas.map(t=>{const c=t['ID tramo'],e=estadoRuta(c),cab=t['Nodo o central']!==grupo?(grupo=t['Nodo o central'],`<h3 class="lev-grupo-titulo rapida">${esc(grupo)}<span>${filas.filter(x=>x['Nodo o central']===grupo).length} tramos</span></h3>`):'';
      return `${cab}<button type="button" class="lev-item" data-fo-tramo="${esc(c)}"><div><strong>${esc(c)}</strong><div class="record-meta">${esc(t['Cable de diseño'])} · ${Math.round(num(t['Longitud de diseño (m)'])??0)} m · ${esc(t['Postes candidatos (N°)'])} candidatos${t['Lo levanta']?' · '+esc(t['Lo levanta']):''}</div></div>
        <div class="lev-estados"><span class="status ${e.control==='OK'?'sent':e.control==='Sin levantar'?'':'error'}">${esc(e.control)}</span><span class="lev-envio">${e.levantados} apoyos · ${e.aptos} aptos</span></div></button>`;}).join('')||'<p class="muted">Ningún tramo coincide.</p>'}</div>`;
}
function pantallaTramo(){
  const t=vista.tramo,T=idx.Ruta.get(t),e=estadoRuta(t),cand=apoyosDelTramo(t).sort((a,b)=>(num(a['Progresiva en el tramo (m)'])??0)-(num(b['Progresiva en el tramo (m)'])??0));
  const extra=levantadosEn(t).filter(c=>!cand.some(a=>a['Código de apoyo']===c)).map(c=>idx.Apoyos.get(c)).filter(Boolean);
  const lista=[...cand,...extra],punto=a=>{const p=valores('Apoyos',a['Código de apoyo']),gps=num(p['Latitud medida'])!==null?{lat:num(p['Latitud medida']),lon:num(p['Longitud medida'])}:posicion(a);return gps&&{...gps,codigo:a['Código de apoyo'],color:COLOR[estadoApoyo(a['Código de apoyo']).veredicto]??'var(--fo-candidato)'};};
  return `<div class="lev-ficha-top"><button type="button" class="text-button" data-fo-volver="tramos">← Todos los tramos</button><span class="status ${e.control==='OK'?'sent':e.control==='Sin levantar'?'':'error'}">${esc(e.control)}</span></div>
    <h2>${esc(t)}</h2><p class="lev-aviso">${esc(SEGURIDAD)}</p>
    <dl class="lev-pre"><div><dt>Nodo</dt><dd>${esc(T['Nodo o central'])}</dd></div><div><dt>Cable de diseño</dt><dd>${esc(T['Cable de diseño'])}</dd></div><div><dt>Longitud de diseño</dt><dd>${Math.round(num(T['Longitud de diseño (m)'])??0)} m</dd></div><div><dt>Permisos del tramo</dt><dd>${esc(e.permisos||'—')}</dd></div></dl>
    ${mapa([K.trazado[t]??[]],lista.map(punto).filter(Boolean),aqui)}
    <p class="field-hint fo-leyenda"><i style="background:var(--fo-apto)"></i>Apto <i style="background:var(--fo-revisar)"></i>A revisar <i style="background:var(--fo-no)"></i>No apto <i style="background:var(--fo-nada)"></i>No encontrado <i style="background:var(--fo-candidato)"></i>Sin levantar <i style="background:var(--fo-yo)"></i>Tú</p>
    <div class="fo-acciones"><button type="button" class="btn btn-camera" data-fo-gps><svg><use href="#i-pin"/></svg>Estoy en el poste</button><button type="button" class="btn btn-secondary" data-fo-ruta>Ficha de la ruta (al terminar)</button></div>
    <div id="fo-candidatos"></div>
    <h3 class="lev-grupo-titulo">Postes del tramo <span>${e.levantados} levantados · ${e.aptos} aptos · ${lista.length} en la lista</span></h3>
    <div class="lev-lista">${lista.map(a=>{const c=a['Código de apoyo'],s=estadoApoyo(c),env=estadoEnvio('Apoyos',c);return `<button type="button" class="lev-item" data-fo-apoyo="${esc(c)}"><div><strong>${esc(c)}</strong><div class="record-meta">${a['Progresiva en el tramo (m)']!==''?Math.round(num(a['Progresiva en el tramo (m)'])??0)+' m · ':''}placa SEC ${esc(a['Placa SEC']||'—')} · ${esc(a['Propiedad SEC']||'')}</div></div>
      <div class="lev-estados">${s.veredicto?`<span class="status ${s.veredicto==='Apto'?'sent':s.veredicto==='A revisar'||s.veredicto==='Incompleto'?'':'error'}">${esc(s.veredicto)}</span>`:''}<span class="lev-envio ${env.clase}">${esc(s.control==='Sin levantar'?'Sin levantar':s.control)}</span></div></button>`;}).join('')}</div>`;
}
function campoHTML(h,c,v,{soloLectura=false}={}){
  const val=v[c.key]??'',id='fo-c-'+K.hojas[h].campos.indexOf(c),attr=`id="${id}" data-fo-campo="${esc(c.key)}"${soloLectura?' readonly':''}`;let input;
  if(c.type==='list'&&!soloLectura)input=`<select ${attr}><option value=""></option>${c.options.map(o=>`<option${o===val?' selected':''}>${esc(o)}</option>`).join('')}</select>`;
  else if(c.type==='date'&&!soloLectura)input=`<input ${attr} type="date" value="${esc(val)}">`;
  else if((c.type==='decimal'||c.type==='whole')&&!soloLectura)input=`<input ${attr} type="text" inputmode="${c.type==='whole'?'numeric':'decimal'}" value="${esc(val)}" autocomplete="off">`;
  else if(soloLectura)input=`<input ${attr} value="${esc(val)}">`;
  else input=`<textarea ${attr} rows="2" maxlength="2000">${esc(val)}</textarea>`;
  return `<label class="lev-campo">${esc(c.key)}${input}</label>`;
}
function bloqueFotos(h,codigo,sufijo,minimo){
  const fs=fotosDe(h,codigo),lista=tomas(sufijo);
  return `<fieldset class="lev-grupo"><legend>Fotos · mínimo ${minimo}</legend><ol class="fo-tomas">${lista.map((t,i)=>`<li${i<minimo?' class="fo-req"':''}>${esc(t)}</li>`).join('')}</ol>
    <div class="proto-actions"><button type="button" class="btn btn-camera" data-fo-foto="camera"><svg><use href="#i-camera"/></svg>Cámara</button><button type="button" class="btn btn-secondary" data-fo-foto="gallery"><svg><use href="#i-plus"/></svg>Galería</button></div>
    ${fs.length?`<div class="proto-thumbs">${fs.map(f=>{const u=URL.createObjectURL(f.blob);urls.push(u);return `<div class="photo-tile"><img src="${u}" alt=""><code>${esc(nombreFoto(f))} · ${f.status==='sent'?'✓ Dropbox':'○ En el teléfono'}</code>${f.status==='sent'?'':`<button type="button" class="remove-photo" data-fo-quitar="${esc(f.id)}" aria-label="Quitar fotografía">×</button>`}</div>`;}).join('')}</div>`:''}</fieldset>`;
}
function pantallaApoyo(){
  const c=vista.apoyo,A=idx.Apoyos.get(c),v=valores('Apoyos',c),s=estadoApoyo(c),env=estadoEnvio('Apoyos',c),r=reg('Apoyos',c);
  const paso=vista.paso??1,campos=amarillas('Apoyos'),p1=PASO1.map(k=>campos.find(x=>x.key===k)).filter(Boolean),p2=campos.filter(x=>!PASO1.includes(x.key)&&!AUTO.includes(x.key));
  return `<div class="lev-ficha-top"><button type="button" class="text-button" data-fo-volver="tramo">← ${esc(vista.tramo)}</button><span id="fo-control" class="status ${s.control==='OK'?'sent':s.control==='Sin levantar'?'':'error'}">${esc(s.control)}</span></div>
    <h2>${esc(c)}${s.veredicto?` · <span id="fo-veredicto">${esc(s.veredicto)}</span>`:''}</h2><p class="lev-aviso">${esc(SEGURIDAD)}</p>
    <dl class="lev-pre">${['Placa SEC','Propiedad SEC','Material SEC','Altura SEC (bruta)','Tensión SEC','Distancia a la fibra (m)'].filter(k=>A?.[k]!==''&&A?.[k]!==undefined).map(k=>`<div><dt>${esc(k)}</dt><dd>${esc(A[k])}</dd></div>`).join('')}
      <div><dt>Tramo levantado</dt><dd>${esc(v['Tramo levantado']||vista.tramo)}</dd></div><div><dt>GPS</dt><dd>${r?.gps?esc(gpsLabel(r.gps,'camera')):'Sin tomar'}${A&&posicion(A)?` · <a href="https://www.google.com/maps?q=${posicion(A).lat},${posicion(A).lon}" target="_blank" rel="noopener noreferrer">Ver en Google Maps</a>`:''}</dd></div></dl>
    <div class="fo-acciones"><button type="button" class="btn btn-camera" data-fo-gps-aqui><svg><use href="#i-pin"/></svg>Estoy en este poste: tomar GPS</button></div>
    <div class="fo-pasos"><button type="button" class="${paso===1?'activo':''}" data-fo-paso="1">1 · Ficha del apoyo</button><button type="button" class="${paso===2?'activo':''}" data-fo-paso="2">2 · Resto de la ficha</button></div>
    <fieldset class="lev-grupo lev-rapida">${(paso===1?p1:p2).map(x=>campoHTML('Apoyos',x,v)).join('')}</fieldset>
    ${bloqueFotos('Apoyos',c,'apoyo',minFotos('fotosApoyo'))}
    <div class="lev-acciones"><span id="fo-envio" class="lev-envio ${env.clase}">${esc(env.texto)}${r?.error?' · '+esc(r.error):''}</span><button type="button" class="btn btn-primary" data-fo-enviar ${busy?'disabled':''}>Enviar a Dropbox</button></div>`;
}
function pantallaRuta(){
  const t=vista.tramo,v=valores('Ruta',t),e=estadoRuta(t),env=estadoEnvio('Ruta',t),r=reg('Ruta',t);
  return `<div class="lev-ficha-top"><button type="button" class="text-button" data-fo-volver="tramo">← ${esc(t)}</button><span id="fo-control" class="status ${e.control==='OK'?'sent':e.control==='Sin levantar'?'':'error'}">${esc(e.control)}</span></div>
    <h2>Ficha de la ruta · ${esc(t)}</h2><p class="lev-aviso">${esc(SEGURIDAD)}</p>
    <dl class="lev-pre"><div><dt>Permisos del tramo</dt><dd id="fo-permisos">${esc(e.permisos||'—')}</dd></div><div><dt>Apoyos levantados</dt><dd>${e.levantados}</dd></div><div><dt>Apoyos aptos</dt><dd>${e.aptos}</dd></div></dl>
    <fieldset class="lev-grupo lev-rapida">${amarillas('Ruta').filter(x=>!AUTO.includes(x.key)).map(x=>campoHTML('Ruta',x,v)).join('')}</fieldset>
    ${bloqueFotos('Ruta',t,'ruta',minFotos('fotosRuta'))}
    <div class="lev-acciones"><span id="fo-envio" class="lev-envio ${env.clase}">${esc(env.texto)}${r?.error?' · '+esc(r.error):''}</span><button type="button" class="btn btn-primary" data-fo-enviar ${busy?'disabled':''}>Enviar a Dropbox</button></div>`;
}

// --- Editing -----------------------------------------------------------------------------------------------------------
const actual=()=>vista.pantalla==='apoyo'?['Apoyos',vista.apoyo]:['Ruta',vista.tramo];
function nuevo(h,c){return {clave:clave(h,c),comuna,hoja:h,codigo:c,valores:{},gps:null,sent:null,error:''};}
async function guardar(h,c,cambios){
  const r=reg(h,c)??nuevo(h,c);
  for(const [k,x] of Object.entries(cambios)){if(x===''||x===null||x===undefined)delete r.valores[k];else r.valores[k]=x;}
  if(!r.valores['Fecha'])r.valores['Fecha']=chileDate();
  r.valores['Levantó']=ctx.config().email;   // automatic (decision of 06-11): the session; name and title when the people registry exists
  if(h==='Apoyos'&&!r.valores['Tramo levantado'])r.valores['Tramo levantado']=vista.tramo;
  r.error='';r.updatedAt=new Date().toISOString();registros.set(r.clave,r);await put('registros',[r]);
}
function refrescar(){
  const [h,c]=actual();
  const e=h==='Apoyos'?estadoApoyo(c):estadoRuta(c),env=estadoEnvio(h,c);
  $('fo-control').textContent=e.control;$('fo-control').className='status '+(e.control==='OK'?'sent':e.control==='Sin levantar'?'':'error');
  if($('fo-veredicto'))$('fo-veredicto').textContent=e.veredicto;if($('fo-permisos'))$('fo-permisos').textContent=e.permisos||'—';
  $('fo-envio').textContent=env.texto;$('fo-envio').className='lev-envio '+env.clase;
}
// The next free NC code: an «NC» row of the planilla nobody on this phone has used. The office reassigns on a clash.
function siguienteNC(){const usados=new Set([...registros.values()].filter(r=>r.comuna===comuna).map(r=>r.codigo));return [...idx.Apoyos.keys()].find(c=>c.includes('-NC-')&&!usados.has(c));}
async function estoyEnElPoste(){
  ctx.toast('Obteniendo ubicación GPS…');
  const fix=await requestFix(()=>ctx.toast('Ubicación desactivada: activa el GPS.'));
  if(!fix){ctx.toast('No se pudo obtener la ubicación.');return;}
  aqui=fix;
  const cerca=[...idx.Apoyos.values()].filter(a=>!String(a['Código de apoyo']).includes('-NC-')).map(a=>({a,d:posicion(a)?distancia(fix,posicion(a)):Infinity})).filter(x=>x.d<=Math.max(BUSQUEDA.radio,fix.accuracy)).sort((x,y)=>x.d-y.d).slice(0,8);
  render();
  $('fo-candidatos').innerHTML=`<div class="lev-confirmar"><p><strong>¿Cuál es este poste?</strong> GPS ±${fix.accuracy} m.${fix.accuracy>BUSQUEDA.precision?` La precisión es peor que ${BUSQUEDA.precision} m: confirma por la placa antes de elegir.`:''}</p>
    ${cerca.length?`<div class="lev-lista">${cerca.map(({a,d})=>`<button type="button" class="lev-item" data-fo-elegir="${esc(a['Código de apoyo'])}"><div><strong>${esc(a['Código de apoyo'])}</strong><div class="record-meta">placa SEC ${esc(a['Placa SEC']||'—')} · ${esc(a['Propiedad SEC']||'')} · ${esc(a['Tramo más próximo'])}</div></div><div class="lev-estados"><span class="lev-envio">a ${d.toFixed(1).replace('.',',')} m</span></div></button>`).join('')}</div>`:`<p class="field-hint">No hay postes del catastro a menos de ${BUSQUEDA.radio} m.</p>`}
    <div class="lev-botones"><button type="button" class="btn btn-secondary" data-fo-nc>Poste no catastrado</button></div></div>`;
}
// Opening a pole from the walk records its GPS and links it to the previous pole of the same tramo (span and next code).
async function abrirApoyo(codigo,{conGps=false,nc=false}={}){
  vista={...vista,pantalla:'apoyo',apoyo:codigo,paso:1};
  if(conGps&&aqui){
    const previo=vista.ultimo?.[vista.tramo];
    await guardar('Apoyos',codigo,{'Latitud medida':aqui.lat.toFixed(6),'Longitud medida':aqui.lon.toFixed(6),'Tramo levantado':vista.tramo,
      '¿Se encontró el poste?':reg('Apoyos',codigo)?.valores['¿Se encontró el poste?']??(nc?'Poste no catastrado':'Sí: coincide la placa')});
    reg('Apoyos',codigo).gps=aqui;await put('registros',[reg('Apoyos',codigo)]);
    if(previo&&previo!==codigo&&reg('Apoyos',previo)?.gps&&!reg('Apoyos',previo).valores['Siguiente apoyo (código)']){
      const m=Math.round(distancia(reg('Apoyos',previo).gps,aqui)*10)/10;
      await guardar('Apoyos',previo,{'Siguiente apoyo (código)':codigo,'Vano al siguiente apoyo (m)':String(m)});
      ctx.toast(`Vano desde ${previo}: ${String(m).replace('.',',')} m (se puede corregir en la ficha).`);
    }
    vista.ultimo={...(vista.ultimo??{}),[vista.tramo]:codigo};
  }
  render();window.scrollTo({top:0,behavior:'instant'});
}
async function agregarFotos(lista,origen){
  const [h,c]=actual(),sufijo=h==='Apoyos'?'apoyo':'ruta',fix=await requestFix(),fecha=reg(h,c)?.valores['Fecha']||chileDate();
  let n=Math.max(0,...fotosDe(h,c).map(f=>f.n||0));const nuevas=[];
  for(const file of lista){
    if(!file.size||file.size>25*1024*1024){ctx.toast('Cada foto debe pesar entre 1 byte y 25 MB.');continue;}
    const at=new Date().toISOString();
    let blob=await processImage(file,[`${c} · Fibra ${sufijo}`,`${fecha.split('-').reverse().join('-')} · ${new Intl.DateTimeFormat('es-CL',{timeZone:'America/Santiago',dateStyle:'short',timeStyle:'short'}).format(new Date(at))}`,gpsLabel(fix,origen),ctx.config().email]);
    if(!blob){ctx.toast('No se pudo procesar la foto.');continue;}
    if(fix)blob=await withExif(blob,fix);
    nuevas.push({id:randomId(),clave:clave(h,c),comuna,hoja:h,codigo:c,sufijo,blob,gps:fix,fecha,at,status:'pending',n:++n});
  }
  if(!nuevas.length)return;
  await put('fotos',nuevas);fotos.push(...nuevas);await guardar(h,c,{});render();
}

// --- Sending: photos first, then the record's JSON; nothing leaves the phone until Dropbox confirms -----------------
const nombreFoto=f=>`${f.codigo}_${f.fecha}_${f.sufijo}-${f.n}.jpg`;
const carpetaFotos=f=>`${ctx.config().root.replace(/\/+$/,'')}/${f.comuna}/Fotos${ctx.config().pilot?'/_PILOTO_CAPTURA':''}/Fibra`;
async function subirFoto(f){
  if(!f.contentHash)f.contentHash=await dropbox.contentHash(f.blob);
  for(let i=0;i<50;i++){const path=carpetaFotos(f)+'/'+nombreFoto(f);
    try{const m=await dropbox.metadata(path);if(m['.tag']==='file'&&m.content_hash===f.contentHash){f.path=m.path_display;return;}f.n+=100;continue;}
    catch(e){if(!(e instanceof dropbox.DropboxError&&e.status===409&&String(e.message).includes('not_found')))throw e;}
    try{const r=await dropbox.api('files/upload',null,{binary:f.blob,args:{path,mode:'add',autorename:false,strict_conflict:true,content_hash:f.contentHash}});f.path=r.path_display;return;}
    catch(e){if(e instanceof dropbox.DropboxError&&e.status===409&&String(e.message).includes('conflict')){f.n+=100;continue;}throw e;}}
  throw new Error('No se pudo asignar un nombre libre a la foto.');
}
async function enviar(h,c){
  const cfg=ctx.config();
  if(!cfg.levantamientoQueue){ctx.toast('El envío no está activado todavía. Todo queda guardado en el teléfono.');return;}
  if(!navigator.onLine){ctx.toast('Sin señal. Todo queda guardado en el teléfono; envía cuando haya cobertura.');return;}
  if(busy)return;busy=true;render();
  const r=reg(h,c)??nuevo(h,c);
  try{
    for(const f of fotosDe(h,c).filter(x=>x.status!=='sent')){await subirFoto(f);f.status='sent';await put('fotos',[f]);}
    const id=randomId(),guardado=new Date().toISOString(),fs=fotosDe(h,c),v=valores(h,c),envio={};
    for(const x of amarillas(h))if(v[x.key]!==undefined&&v[x.key]!=='')envio[x.key]=v[x.key];
    const cuerpo={version:1,tipo:'fibra',app:'evidencias',comuna,hoja:h,codigo:c,id,guardado,registro:cfg.email,piloto:!!cfg.pilot,valores:envio,gps:r.gps??null,
      nc:h==='Apoyos'&&c.includes('-NC-'),fotos:fs.map(f=>({nombre:nombreFoto(f),ruta:f.path,gps:f.gps??null}))};
    const path=`${cfg.levantamientoQueue}/${cfg.pilot?'_PILOTO/':''}Fibra/${comuna}/${c}_${guardado.replace(/[:.]/g,'-')}_${id.slice(0,8)}.json`;
    await dropbox.api('files/upload',null,{binary:new Blob([JSON.stringify(cuerpo,null,1)],{type:'application/json'}),args:{path,mode:'add',autorename:false,strict_conflict:true}});
    r.sent={id,at:guardado,path,huella:huella(r)};r.error='';ctx.toast(`${c} enviado. La planilla se actualiza en el próximo ciclo del servicio.`);
  }catch(e){r.error=e.name==='TimeoutError'?'La respuesta tardó demasiado. Reintenta.':e.message;ctx.toast('No se pudo enviar: '+r.error);}
  finally{registros.set(r.clave,r);await put('registros',[r]);busy=false;render();}
}

// --- Wiring --------------------------------------------------------------------------------------------------------------
export async function setupFibra(context){
  ctx=context;
  for(const r of await all('registros'))registros.set(r.clave,r);
  fotos=await all('fotos');
  const view=$('fibra-view');
  view.addEventListener('click',async e=>{
    const t=e.target.closest('[data-fo-tramo],[data-fo-volver],[data-fo-apoyo],[data-fo-gps],[data-fo-gps-aqui],[data-fo-elegir],[data-fo-nc],[data-fo-ruta],[data-fo-paso],[data-fo-foto],[data-fo-quitar],[data-fo-enviar]');if(!t)return;
    const d=t.dataset;
    if(d.foTramo){vista={...vista,pantalla:'tramo',tramo:d.foTramo};render();window.scrollTo({top:0,behavior:'instant'});}
    else if(d.foVolver){vista={...vista,pantalla:d.foVolver};render();}
    else if(d.foApoyo&&vista.pantalla==='tramo')await abrirApoyo(d.foApoyo);
    else if('foGps'in d)await estoyEnElPoste();
    else if('foGpsAqui'in d){ctx.toast('Obteniendo ubicación GPS…');const fix=await requestFix(()=>ctx.toast('Ubicación desactivada: activa el GPS.'));if(!fix){ctx.toast('No se pudo obtener la ubicación.');return;}aqui=fix;await abrirApoyo(vista.apoyo,{conGps:true});ctx.toast(`GPS tomado ±${fix.accuracy} m.`);}
    else if(d.foElegir)await abrirApoyo(d.foElegir,{conGps:true});
    else if('foNc'in d){const c=siguienteNC();if(!c){ctx.toast('No quedan códigos NC libres en la planilla: avisa a la oficina.');return;}await abrirApoyo(c,{conGps:true,nc:true});ctx.toast(`Poste no catastrado: código ${c}. La oficina lo confirma al recibirlo.`);}
    else if('foRuta'in d){vista={...vista,pantalla:'ruta'};render();window.scrollTo({top:0,behavior:'instant'});}
    else if(d.foPaso){vista={...vista,paso:Number(d.foPaso)};render();}
    else if(d.foFoto){const input=document.createElement('input');input.type='file';input.accept='image/*';if(d.foFoto==='camera')input.capture='environment';else input.multiple=true;input.onchange=()=>agregarFotos([...input.files],d.foFoto);input.click();}
    else if(d.foQuitar){await del('fotos',[d.foQuitar]);fotos=fotos.filter(f=>f.id!==d.foQuitar);render();}
    else if('foEnviar'in d){const [h,c]=actual();await enviar(h,c);}
  });
  view.addEventListener('input',e=>{
    if(e.target.id==='fo-buscar'){filtro.texto=e.target.value;clearTimeout(timer);timer=setTimeout(()=>{render();const b=$('fo-buscar');b?.focus();b?.setSelectionRange(b.value.length,b.value.length);},250);return;}
    const k=e.target.dataset?.foCampo;if(!k)return;clearTimeout(timer);const [h,c]=actual(),x=e.target.value;timer=setTimeout(async()=>{await guardar(h,c,{[k]:x});refrescar();},300);
  });
  view.addEventListener('change',async e=>{
    if(e.target.id==='fo-nodo'){filtro.nodo=e.target.value;render();return;}
    const k=e.target.dataset?.foCampo;if(!k)return;clearTimeout(timer);const [h,c]=actual();await guardar(h,c,{[k]:e.target.value});refrescar();
  });
}
export async function showFibra(c){
  if(comuna!==c){$('fibra-view').innerHTML='<p class="muted">Cargando la planilla de fibra…</p>';try{await cargar(c);}catch(e){$('fibra-view').innerHTML=`<p class="form-error">${esc(e.message)}</p>`;return;}vista={pantalla:'tramos'};filtro={texto:'',nodo:''};}
  render();
}
